import { performance } from 'firebase/app';
import * as React from 'react';
import { useFirebaseApp } from '..';

export interface SuspensePerfProps {
  children: React.ReactNode;
  traceId: string;
  fallback: React.ReactNode;
  firePerf?: performance.Performance;
}

function getPerfFromContext(): performance.Performance {
  const firebaseApp = useFirebaseApp();
  if (!firebaseApp) {
    throw new Error(
      'Firebase not found in context. Either pass it directly to a reactfire hook, or wrap your component in a FirebaseAppProvider'
    );
  }

  const perfFunc = firebaseApp.performance;

  if (!perfFunc || !perfFunc()) {
    throw new Error(
      "No perf object off of Firebase. Did you forget to import 'firebase/performance' in a component?"
    );
  }

  return perfFunc();
}

export function SuspenseWithPerf({
  children,
  traceId,
  fallback,
  firePerf
}: SuspensePerfProps) {
  firePerf = firePerf || getPerfFromContext();

  const Fallback = () => {
    React.useLayoutEffect(() => {
      const trace = firePerf.trace(traceId);
      trace.start();

      return () => {
        trace.stop();
      };
    }, [traceId]);

    return <>{fallback}</>;
  };

  return <React.Suspense fallback={<Fallback />}>{children}</React.Suspense>;
}

import { IMetricListener } from "./IMetricListener";
import { IMetricContext } from "./contexts";
import { LogService } from "..";

/**
 * Tracks metrics.
 * @category Metrics
 */
export class Metrics {

    private listeners: IMetricListener[] = [];
    private requestStartTimes: { [contextId: string]: number } = {};
    private uid = 0;

    /**
     * Creates a new Metrics handler with optional parent handler. When
     * a parent handler is defined, metrics will be automatically published
     * upwards to the parent.
     * @param {Metrics} parent Optional parent for upstream metrics.
     */
    constructor(parent: Metrics = null) {
        if (parent !== null) {
            this.registerListener({
                onIncrement(metricName: string, context: IMetricContext, amount: number) {
                    parent.listeners.forEach(h => h.onIncrement(metricName, context, amount));
                },
                onDecrement(metricName: string, context: IMetricContext, amount: number) {
                    parent.listeners.forEach(h => h.onDecrement(metricName, context, amount));
                },
                onReset(metricName: string, context: IMetricContext) {
                    parent.listeners.forEach(h => h.onReset(metricName, context));
                },
                onStartMetric(metricName: string, context: IMetricContext): void {
                    parent.listeners.forEach(h => h.onStartMetric(metricName, context));
                },
                onEndMetric(metricName: string, context: IMetricContext, timeMs: number): void {
                    parent.listeners.forEach(h => h.onEndMetric(metricName, context, timeMs));
                },
            });
        }
    }

    /**
     * Registers a metric listener.
     * @param {IMetricListener} listener The listener.
     */
    public registerListener(listener: IMetricListener) {
        this.listeners.push(listener);
    }

    /**
     * De-registers a metric listener.
     * @param {IMetricListener} listener The listener.
     */
    public unregisterListener(listener: IMetricListener) {
        const idx = this.listeners.indexOf(listener);
        if (idx !== -1) this.listeners.splice(idx, 1);
    }

    /**
     * Starts a timer on a metric.
     * @param {string} metricName The metric name.
     * @param {IMetricContext} context The metric context. Expected to have a unique ID.
     */
    public start(metricName: string, context: IMetricContext) {
        this.requestStartTimes[context.uniqueId] = new Date().getTime();
        this.listeners.forEach(h => h.onStartMetric(metricName, context));
    }

    /**
     * Ends a timer on a metric.
     * @param {string} metricName The metric name.
     * @param {IMetricContext} context The metric context. Expected to have a unique ID.
     */
    public end(metricName: string, context: IMetricContext) {
        const timeMs = (new Date().getTime()) - this.requestStartTimes[context.uniqueId];
        delete this.requestStartTimes[context.uniqueId];
        this.listeners.forEach(h => h.onEndMetric(metricName, context, timeMs));

        // Trim the context for logging
        const trimmedContext = {};
        for (const key of Object.keys(context)) {
            if (key === 'client') {
                const client = context[key];
                trimmedContext[key] = `<MatrixClient ${client['userId'] || 'NoCachedUserID'}>`;
            } else if (key === 'intent') {
                const intent = context[key];
                trimmedContext[key] = `<Intent ${intent['userId'] || 'NoImpersonatedUserID'}>`;
            } else {
                trimmedContext[key] = context[key];
            }
        }

        LogService.trace("Metrics", metricName, trimmedContext, timeMs);
    }

    /**
     * Increments a metric.
     * @param {string} metricName The metric name.
     * @param {IMetricContext} context The metric context. Expected to have a unique ID.
     * @param {number} amount The amount.
     */
    public increment(metricName: string, context: IMetricContext, amount: number) {
        this.listeners.forEach(h => h.onIncrement(metricName, context, amount));
    }

    /**
     * Decrements a metric.
     * @param {string} metricName The metric name.
     * @param {IMetricContext} context The metric context. Expected to have a unique ID.
     * @param {number} amount The amount.
     */
    public decrement(metricName: string, context: IMetricContext, amount: number) {
        this.listeners.forEach(h => h.onDecrement(metricName, context, amount));
    }

    /**
     * Resets a metric.
     * @param {string} metricName The metric name.
     * @param {IMetricContext} context The metric context. Expected to have a unique ID.
     */
    public reset(metricName: string, context: IMetricContext) {
        this.listeners.forEach(h => h.onReset(metricName, context));
    }

    /**
     * Assigns a unique ID to the context object, returning it back.
     * @param {IMetricContext} context The context to modify.
     * @returns {IMetricContext} The provided context.
     */
    public assignUniqueContextId(context: IMetricContext): IMetricContext {
        context.uniqueId = `${new Date().getTime()}-${this.uid++}`;
        return context;
    }
}

import { Component, OnInit } from '@angular/core';
import { NavController, ModalController } from '@ionic/angular';
import { Venue } from '../../../providers/venue';
import { PageHelper } from '../../../providers/page-helper';
import { Logger } from '../../../providers/logger';
import { Router, ActivatedRoute, ParamMap } from '@angular/router';
import { LTCache } from '../../../providers/lt-cache';

@Component({
  selector: 'app-venue-list',
  templateUrl: './venue-list.page.html',
  styleUrls: ['./venue-list.page.scss'],
})
export class VenueListPage implements OnInit {
  private _className = 'VenueListPage';

  // form data object
  venue: any;

  // venue list
  venues: any;

  // Current signed in users email address
  usersEmail: string;

  constructor(
    public navCtrl: NavController,
    public venueProvider: Venue,
    public cache: LTCache,
    public modalCtrl: ModalController,
    public route: ActivatedRoute,
    public logger: Logger,
    public pageHelper: PageHelper,
    public router: Router
  ) {
    this.usersEmail = cache.getValue(cache.KEY_USER_LOGIN_EMAIL);
    this.usersEmail = this.usersEmail ? this.usersEmail.toLowerCase() : null;

    this.venue = {
      id: '',
      locationId: '',
      description: '',
      categoryId: '',
      active: '',
      hidden: '',
      name: '',
      title: '',
      tags: '',
      pageSize: '50',
      pageNumber: 1,
      dataResultCount: 0
    };
  } // end constructor

  ngOnInit() {
    this.logger.entry(this._className, 'ngOnInit');
    this.route.queryParams.subscribe((params) => {
      this.venue.id = params['VenueId'];
      this.venue.locationId = params['LocationId'];
      this.venue.categoryId = params['CategoryId'];
      this.venue.description = params['Description'];
      this.venue.title = params['Title'];
      this.venue.name = params['Name'];
      this.venue.active = params['Active'];
      this.venue.hidden = params['Hidden'];
      this.venue.pageSize = params['ResultsPerPage'];
      this.venue.tags = params['Tags'];
      this.venue.pageNumber = 1;
      this.logger.entry(
        this._className,
        'ngOnInit this.venue.id:' + this.venue.id
      );
    });
  }

  /**
   * This method is called on every page view
   **/
  ionViewWillEnter() {
    this.logger.entry(this._className, 'ionViewWillEnter');
    this._searchVenue();
  }

  /**
   * Navigate to the previous result set page
   */
  async previousPage() {
    this.venue.pageNumber--;
    this.logger.entry(this._className, 'previousPage');
    this._searchVenue();
  }

  /**
   * Navigate to the next result set page
   */
  async nextPage() {
    this.venue.pageNumber++;
    this.logger.entry(this._className, 'nextPage');
    this._searchVenue();
  }

  /**
   * This method loads venues
   **/
  async _searchVenue() {
    this.logger.entry(this._className, '_searchVenue');
    await this.pageHelper.showLoader();

    // Load the users profile and update the UI
    this.venueProvider.getSearchVenue(this.venue, false, false, true).subscribe(
      (resp) => {
        this.pageHelper.hideLoader();
        if (resp != null && resp.dataList != null) {
          this.venues = resp.dataList;
          this.venue.dataResultCount = resp.dataResultCount;
          this.venue.pageSize = resp.pageSize;
          this.logger.trace(this._className, 'this.venues.dataResultCount', this.venues.dataResultCount);
        }
      },
      (err) => {
        this.pageHelper.processRequestError(err).subscribe((resp) => {
          this._searchVenue();
        });
      }
    );
  }

}

import { writeStorage } from "@rehooks/local-storage";
import { OperationsResponse } from "common-ui";
import { DEFAULT_GROUP_STORAGE_KEY } from "../../../../components/group-select/useStoredDefaultGroup";
import { PcrPrimerEditPage } from "../../../../pages/seqdb/pcr-primer/edit";
import { mountWithAppContext } from "../../../../test-util/mock-app-context";
import { PcrPrimer } from "../../../../types/seqdb-api/resources/PcrPrimer";

// Mock out the Link component, which normally fails when used outside of a Next app.
jest.mock("next/link", () => ({ children }) => <div>{children}</div>);

/** Mock Kitsu "get" method. */
const mockGet = jest.fn(async path => {
  if (path === "seqdb-api/pcr-primer/100") {
    // The request for the primer returns the test primer.
    return { data: TEST_PRIMER };
  } else {
    // Requests for the selectable resources (linked group, region, etc.) return an empty array.
    return { data: [] };
  }
});

/** Mock axios for operations requests. */
const mockPatch = jest.fn();

/** Mock next.js' router "push" function for navigating pages. */
const mockPush = jest.fn();

const apiContext: any = {
  apiClient: { get: mockGet, axios: { patch: mockPatch } }
};

describe("PcrPrimer edit page", () => {
  beforeEach(() => {
    // Set the deault group selection:
    writeStorage(DEFAULT_GROUP_STORAGE_KEY, "aafc");
    jest.clearAllMocks();
  });

  it("Provides a form to add a PcrPrimer.", async () => {
    mockPatch.mockReturnValueOnce({
      data: [
        {
          data: {
            id: "1",
            type: "pcr-primer"
          },
          status: 201
        }
      ] as OperationsResponse
    });

    const wrapper = mountWithAppContext(
      <PcrPrimerEditPage router={{ query: {}, push: mockPush } as any} />,
      { apiContext }
    );

    // Edit the primer name.
    wrapper.find(".name-field input").simulate("change", {
      target: { name: "name", value: "New PcrPrimer" }
    });

    // Submit the form.
    wrapper.find("form").simulate("submit");

    // Wait for the primer form to load.
    await new Promise(setImmediate);
    wrapper.update();

    expect(mockPatch).lastCalledWith(
      "/seqdb-api/operations",
      [
        {
          op: "POST",
          path: "pcr-primer",
          value: {
            attributes: {
              group: "aafc",
              lotNumber: 1,
              name: "<NAME>",
              seq: "",
              type: "PRIMER"
            },
            id: "00000000-0000-0000-0000-000000000000",
            type: "pcr-primer"
          }
        }
      ],
      expect.anything()
    );

    // The user should be redirected to the new primer's details page.
    expect(mockPush).lastCalledWith("/seqdb/pcr-primer/view?id=1");
  });

  it("Renders an error after form submit if one is returned from the back-end.", async () => {
    // The patch request will return an error.
    mockPatch.mockImplementationOnce(() => ({
      data: [
        {
          errors: [
            {
              detail: "name size must be between 1 and 10",
              status: "422",
              title: "Constraint violation"
            }
          ],
          status: 422
        }
      ] as OperationsResponse
    }));

    const wrapper = mountWithAppContext(
      <PcrPrimerEditPage router={{ query: {}, push: mockPush } as any} />,
      { apiContext }
    );

    // Submit the form.
    wrapper.find("form").simulate("submit");

    // Wait for the primer form to load.
    await new Promise(setImmediate);
    wrapper.update();

    wrapper.update();
    expect(wrapper.find(".alert.alert-danger").text()).toEqual(
      "Constraint violation: name size must be between 1 and 10"
    );
    expect(mockPush).toBeCalledTimes(0);
  });

  it("Provides a form to edit a PcrPrimer.", async () => {
    // The patch request will be successful.
    mockPatch.mockReturnValueOnce({
      data: [
        {
          data: {
            id: "1",
            type: "pcr-primer"
          },
          status: 201
        }
      ] as OperationsResponse
    });

    const wrapper = mountWithAppContext(
      <PcrPrimerEditPage
        router={{ query: { id: 100 }, push: mockPush } as any}
      />,
      { apiContext }
    );

    // The page should load initially with a loading spinner.
    expect(wrapper.find(".spinner-border").exists()).toEqual(true);

    // Wait for the primer form to load.
    await new Promise(setImmediate);
    wrapper.update();

    // // Check that the existing primer's seq value is in the field.
    expect(wrapper.find(".seq-field input").prop("value")).toEqual(
      "ACTACGATCAGCATCGATG"
    );

    // Modify the "designedBy" value.
    wrapper.find(".seq-field input").simulate("change", {
      target: { name: "seq", value: "new seq value" }
    });

    // Submit the form.
    wrapper.find("form").simulate("submit");

    // Wait for the primer form to load.
    await new Promise(setImmediate);
    wrapper.update();

    // "patch" should have been called with a jsonpatch request containing the existing values
    // and the modified one.
    expect(mockPatch).lastCalledWith(
      "/seqdb-api/operations",
      [
        {
          op: "PATCH",
          path: "pcr-primer/1",
          value: {
            attributes: expect.objectContaining({
              application: null,
              group: "aafc",
              name: "ITS1",
              seq: "new seq value"
            }),
            id: "1",
            relationships: {
              region: {
                data: expect.objectContaining({ id: "2", type: "region" })
              }
            },
            type: "pcr-primer"
          }
        }
      ],
      expect.anything()
    );

    // The user should be redirected to the existing primer's details page.
    expect(mockPush).lastCalledWith("/seqdb/pcr-primer/view?id=1");
  });
});

